import re as _re
def restyle(h):
    cmap={'#0e1420':'#231f1b','#e4e8ea':'#f4f0e8','#dde2e5':'#ece6da','#f6f7f7':'#fffdf9','#ff4a12':'#17645f','#ffd400':'#f1c75b',
          '#27303b':'#3a342d','#52606c':'#5f574e','#aab3ba':'#d9d1c3','#c3cad0':'#e3dccd','#cfd6da':'#ece6da','#18202e':'#2a2622',
          '#2c3748':'#3d362f','#dfe5ea':'#efe9de','#1f7a43':'#2f7d4f','#c2331a':'#b5462a','#3b5a82':'#2f7d4f'}
    for a,b in cmap.items(): h=h.replace(a,b)
    h=h.replace("font-family:'Big Shoulders Display',Impact,sans-serif",content.SERIF)
    def fix(m):
        st=m.group(0)
        if 'Newsreader' not in st: return st
        st=_re.sub(r'font-weight:(900|800)','font-weight:600',st)
        st=_re.sub(r'font-size:(\d+)px',lambda k:'font-size:%dpx'%max(20,round(int(k.group(1))*0.74)),st)
        st=_re.sub(r'line-height:(\.\d+)','line-height:1.15',st)
        return st
    h=_re.sub(r'style="[^"]*"',fix,h)
    h=h.replace('text-transform:uppercase','text-transform:none')
    h=_re.sub(r'letter-spacing:[^;"]+','letter-spacing:0',h)
    h=h.replace('border:2px solid #231f1b','border:1px solid #d9d1c3').replace('border-top:4px solid #231f1b','border-top:2px solid #231f1b')
    h=h.replace('background:#17645f;color:#231f1b','background:#17645f;color:#ffffff')
    h=_re.sub(r'(<div style="background:#231f1b)',r'<div class="dark" style="background:#231f1b',h)
    return h
html=restyle(html)
